<div class="toast" id="toast"></div>
<script>
const API='{{ url('/api') }}';
const typeNames = {!! $isAr
    ? json_encode(['stadium'=>'ملعب','hall'=>'قاعة','lounge'=>'استراحة','camp'=>'مخيم'])
    : json_encode(['stadium'=>'Stadium','hall'=>'Hall','lounge'=>'Lounge','camp'=>'Camp'])
!!};
const GOOGLE_PLAY_URL=@json($settings->google_play_url);
const APPLE_STORE_URL=@json($settings->apple_store_url);
function requestAppBooking(){const ua=navigator.userAgent||navigator.vendor||window.opera||'';if(/android/i.test(ua)&&GOOGLE_PLAY_URL){window.location.href=GOOGLE_PLAY_URL;return}if(/iPad|iPhone|iPod/.test(ua)&&APPLE_STORE_URL){window.location.href=APPLE_STORE_URL;return}openModal('downloadAppModal')}
function openModal(id){document.getElementById(id).classList.add('open');document.body.style.overflow='hidden'}
function closeModal(id){document.getElementById(id).classList.remove('open');document.body.style.overflow=''}
document.querySelectorAll('.modal-back').forEach(m=>m.addEventListener('click',e=>{if(e.target===m) closeModal(m.id)}));
function flash(text){const t=document.getElementById('toast');t.textContent=text;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000)}
function message(id,text,ok=false){const el=document.getElementById(id);el.className='msg show '+(ok?'ok':'error');el.textContent=text}
function auth(){return localStorage.getItem('weekend_token')}
function authUser(){try{return JSON.parse(localStorage.getItem('weekend_user')||'null')}catch(e){return null}}
function updateAuthUI(){const u=authUser();if(u){document.querySelectorAll('.nav-actions').forEach(el=>el.innerHTML=`<span class="btn btn-glass">مرحبًا ${u.name||''}</span><button class="btn btn-gold" onclick="logoutUser()">خروج</button>`)} }
async function logoutUser(){try{await fetch(API+'/logout',{method:'POST',headers:{'Authorization':'Bearer '+auth(),'Accept':'application/json'}})}catch(e){}localStorage.removeItem('weekend_token');localStorage.removeItem('weekend_user');location.reload()}
async function submitApi(form,url,msgId){const data=Object.fromEntries(new FormData(form).entries());const r=await fetch(url,{method:'POST',headers:{'Accept':'application/json','Content-Type':'application/json'},body:JSON.stringify(data)});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.message||Object.values(j.errors||{})?.flat()?.[0]||'تعذر إتمام العملية');localStorage.setItem('weekend_token',j.token);localStorage.setItem('weekend_user',JSON.stringify(j.user?.data||j.user||{}));message(msgId,'تم بنجاح',true);setTimeout(()=>location.reload(),650)}
document.getElementById('loginForm').addEventListener('submit',async e=>{e.preventDefault();try{await submitApi(e.target,API+'/login','loginMsg')}catch(err){message('loginMsg',err.message)}});
document.getElementById('registerForm').addEventListener('submit',async e=>{e.preventDefault();try{await submitApi(e.target,API+'/register','registerMsg')}catch(err){message('registerMsg',err.message)}});
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]))}
function hasValue(v){return !(v===null||v===undefined||v===''||(Array.isArray(v)&&!v.length))}
function money(v){if(!hasValue(v)||Number(v)<=0)return null;return Number(v).toLocaleString('ar-SA',{maximumFractionDigits:2})+' ر.س'}
function timeText(v){if(!hasValue(v))return null;return String(v).slice(0,5)}
const dayNames={week_day:'أيام الأسبوع',thursday:'الخميس',friday:'الجمعة',saturday:'السبت',sunday:'الأحد',monday:'الاثنين',tuesday:'الثلاثاء',wednesday:'الأربعاء'};
const detailLabels={
    max_capacity:'السعة القصوى',women_seating:'قسم نساء',kusha:'كوشة',women_seating_capacity:'سعة قسم النساء',women_seating_details:'تفاصيل قسم النساء',women_buffet:'بوفيه نساء',women_buffet_details:'تفاصيل بوفيه النساء',women_tables_count:'طاولات النساء',women_chairs_count:'كراسي النساء',men_seating_available:'قسم رجال',men_seating_capacity:'سعة قسم الرجال',men_seating_details:'تفاصيل قسم الرجال',men_tables_count:'طاولات الرجال',men_chairs_count:'كراسي الرجال',men_buffet:'بوفيه رجال',men_buffet_details:'تفاصيل بوفيه الرجال',buffet:'بوفيه',buffet_details:'تفاصيل البوفيه',
    customize_Category:'فئة الملعب',customize_Place:'نوع المكان',width:'العرض',length:'الطول',amenities:'خدمات ومرافق',cafeteria:'كافتيريا',
    area:'المساحة',bedroom:'غرف نوم',bedroom_number:'عدد غرف النوم',single_bed:'أسرة مفردة',big_bed:'أسرة كبيرة',kitchen:'مطبخ',pool:'مسبح',council:'مجالس',council_number:'عدد المجالس',council_type:'نوع المجلس',
    seating_capacity:'سعة الجلوس',television:'تلفزيون',fireplace:'موقد / مشب',bathroom:'دورات مياه',bathroom_number:'عدد دورات المياه',morning_start_time:'بداية الفترة الصباحية',morning_end_time:'نهاية الفترة الصباحية',evening_start_time:'بداية الفترة المسائية',evening_end_time:'نهاية الفترة المسائية',full_day_start_time:'بداية اليوم الكامل',full_day_end_time:'نهاية اليوم الكامل',all_men_count:'عدد طاولات الرجال',all_women_count:'عدد كراسي النساء'
};
function detailValue(k,v){if(typeof v==='boolean')return v?'متوفر':'غير متوفر';if(['morning_start_time','morning_end_time','evening_start_time','evening_end_time','full_day_start_time','full_day_end_time'].includes(k))return timeText(v);if(k==='area'&&hasValue(v))return Number(v).toLocaleString('ar-SA')+' م²';return esc(v)}
function renderDetails(details){if(!details||typeof details!=='object')return '';const skip=['id','unite_id','created_at','updated_at','type','councils'];const rows=[];Object.entries(details).forEach(([k,v])=>{if(skip.includes(k)||!hasValue(v)||v===false||!detailLabels[k])return;rows.push(`<div class="detail-item"><small>${detailLabels[k]}</small><b>${detailValue(k,v)}</b></div>`)});return rows.length?`<div class="details-section"><h4>تفاصيل المكان</h4><div class="detail-list">${rows.join('')}</div></div>`:''}
function renderImages(images){const urls=(images||[]).map(x=>typeof x==='string'?x:x?.image).filter(Boolean);if(!urls.length)return '';const thumbs=urls.slice(1,5).map(url=>`<div class="details-thumb"><img src="${esc(url)}" alt="صورة الوحدة"></div>`).join('');return `<div class="details-gallery"><div class="details-hero"><img src="${esc(urls[0])}" alt="صورة الوحدة"></div>${thumbs?`<div class="details-thumbs">${thumbs}</div>`:''}</div>`}
function renderPrices(prices){if(!Array.isArray(prices)||!prices.length)return '';const cards=prices.map(p=>{const items=[];[['price','السعر'],['morning_price','الفترة الصباحية'],['evening_price','الفترة المسائية'],['full_price','اليوم الكامل']].forEach(([k,l])=>{const m=money(p[k]);if(m)items.push(`<div class="price-pill"><small>${l}</small><strong>${m}</strong></div>`)});if(p.hourly_enabled){const d=money(p.day_hour_price),n=money(p.night_hour_price);if(d)items.push(`<div class="price-pill"><small>ساعة نهارية</small><strong>${d}</strong></div>`);if(n)items.push(`<div class="price-pill"><small>ساعة ليلية</small><strong>${n}</strong></div>`);if(p.min_booking_minutes)items.push(`<div class="price-pill"><small>الحد الأدنى للحجز</small><strong>${Number(p.min_booking_minutes)} دقيقة</strong></div>`);if(p.day_start&&p.day_end)items.push(`<div class="price-pill"><small>الفترة النهارية</small><strong>${timeText(p.day_start)} - ${timeText(p.day_end)}</strong></div>`)}return items.length?`<div class="price-card"><h5>${dayNames[p.day]||'السعر'}</h5><div class="price-values">${items.join('')}</div></div>`:''}).filter(Boolean);return cards.length?`<div class="details-section"><h4>الأسعار</h4><div class="price-list">${cards.join('')}</div></div>`:''}
function renderOffers(offers){if(!Array.isArray(offers)||!offers.length)return '';const rows=offers.filter(o=>o.status!=='inactive').map(o=>{const vals=[];[['morning_price','صباحي'],['evening_price','مسائي'],['full_day_price','يوم كامل'],['day_hour_price','ساعة نهارية'],['night_hour_price','ساعة ليلية']].forEach(([k,l])=>{const m=money(o[k]);if(m)vals.push(`<span class="chip">${l}: ${m}</span>`)});return `<div class="offer-card"><h5>${esc(o.name||'عرض خاص')}</h5>${o.start||o.end?`<div class="location" style="margin-bottom:8px">${o.start?`من ${esc(o.start)}`:''} ${o.end?`إلى ${esc(o.end)}`:''}</div>`:''}<div class="chips">${vals.join('')}</div></div>`}).join('');return rows?`<div class="details-section"><h4>العروض</h4><div class="price-list">${rows}</div></div>`:''}
function renderFeatures(u){const features=[...(u.features||[]),...(u.new_features||[]),...(u.services||[])];const names=features.map(f=>f.name||f.title||f.service_name||f.description).filter(Boolean);return names.length?`<div class="details-section"><h4>المميزات والخدمات</h4><div class="chips">${names.map(n=>`<span class="chip">✓ ${esc(n)}</span>`).join('')}</div></div>`:''}
async function showUnit(id){openModal('detailsModal');const b=document.getElementById('detailsBody');b.innerHTML='<div style="text-align:center;padding:50px">جاري تحميل التفاصيل...</div>';try{const r=await fetch(API+'/unites/'+id,{headers:{'Accept':'application/json'}});const j=await r.json();if(!r.ok)throw new Error(j.message||'تعذر تحميل التفاصيل');const u=j.data||j;const insurance=u.insurance?`<div class="detail-box"><small>التأمين</small><b>${money(u.insurance_amount)||'مطلوب'}</b></div>`:'';const deposit=u.reservation_deposit?`<div class="detail-box"><small>عربون الحجز</small><b>${money(u.reservation_deposit_amount)||'مطلوب'}</b></div>`:'';const area=hasValue(u.unit_area)?`<div class="detail-box"><small>${u.type==='hall'?'السعة':'المساحة / الأبعاد'}</small><b>${esc(u.unit_area)}</b></div>`:'';const terms=u.additional_terms?`<div class="details-section"><h4>الشروط الإضافية</h4><p style="color:#667672;line-height:1.9">${esc(u.additional_terms)}</p></div>`:'';const refund=u.refund_policy?`<span class="chip">سياسة الاسترجاع: ${esc(u.refund_policy)}</span>`:'';b.innerHTML=`${renderImages(u.images)}<div class="details-head"><div><h2>${esc(u.name)}</h2><div class="location">⌖ ${esc(u.location_name||u.city||'الموقع موضح لدى مقدم الخدمة')}</div></div><button class="btn btn-gold" onclick="requestAppBooking()">احجز عبر التطبيق</button></div><div class="chips"><span class="chip">${typeNames[u.type]||esc(u.type)}</span>${Number(u.rating)>0?`<span class="chip">★ ${Number(u.rating).toFixed(1)} (${Number(u.total_rating_count||0)} تقييم)</span>`:''}${refund}</div>${u.description?`<div class="details-section"><h4>عن المكان</h4><p style="color:#667672;line-height:1.9">${esc(u.description)}</p></div>`:''}${insurance||deposit||area?`<div class="details-section"><h4>معلومات الحجز</h4><div class="details-grid">${area}${deposit}${insurance}</div></div>`:''}${renderDetails(u.details)}${renderFeatures(u)}${renderPrices(u.prices)}${renderOffers(u.offers)}${terms}`;}catch(e){b.innerHTML=`<div class="msg show error">${esc(e.message||'تعذر تحميل تفاصيل الوحدة.')}</div>`}}
(function slider(){const slides=[...document.querySelectorAll('.hero-slide')],dots=[...document.querySelectorAll('.slide-dot')],cta=document.getElementById('heroCta');if(slides.length<2)return;let i=0;setInterval(()=>{slides[i].classList.remove('active');dots[i]?.classList.remove('active');i=(i+1)%slides.length;slides[i].classList.add('active');dots[i]?.classList.add('active');const t=slides[i].dataset.title,s=slides[i].dataset.subtitle,bt=slides[i].dataset.buttonText,bu=slides[i].dataset.buttonUrl;if(t)document.getElementById('heroTitle').textContent=t;if(s)document.getElementById('heroSubtitle').textContent=s;if(cta){if(bt){cta.textContent=bt;cta.href=bu||'#discover';cta.style.display='inline-flex'}else{cta.style.display='none'}}},6000)})();
updateAuthUI();
</script>
</body>
</html>
